create table if not exists user_profile_preferences (user_id text primary key references users(id) on delete cascade, display_name text, timezone text, updated_at timestamptz not null);
create table if not exists project_credentials (id text primary key, project_id text not null references projects(id) on delete cascade, name text not null, secret_ref text not null, fingerprint text, created_at timestamptz not null, updated_at timestamptz not null);
create table if not exists project_context_entries (id text primary key, project_id text not null references projects(id) on delete cascade, user_id text references users(id) on delete cascade, scope text not null check (scope in ('workspace','shared_project','personal_project')), name text not null, content text not null, created_at timestamptz not null, updated_at timestamptz not null);
create table if not exists user_notifications (id text primary key, user_id text not null references users(id) on delete cascade, type text not null, title text not null, link_path text, read_at timestamptz, created_at timestamptz not null);
create table if not exists project_alert_rules (id text primary key, project_id text not null references projects(id) on delete cascade, alert_type text not null, enabled boolean not null default true, created_at timestamptz not null, updated_at timestamptz not null);
alter table project_chat_threads add column if not exists title text, add column if not exists pinned_at timestamptz;
alter table agent_task_artifacts add column if not exists media_type text, add column if not exists preview_text text;
create table if not exists task_follow_ups (id text primary key, task_id text not null references agent_tasks(id) on delete cascade, prompt text not null, created_at timestamptz not null);
